          </div>

          <div className="surface" style={{padding: 20}}>
            <h2 style={{fontSize: 13, fontWeight: 600, marginBottom: 14, textTransform: 'uppercase', letterSpacing: '0.04em', color: 'var(--text-secondary)'}}>Format · tech specs</h2>
            <KVGrid entries={[
