                <tbody>
                  {filtered.map(f => (
                    <tr key={f.id} className={f.id === selectedId ? 'selected' : ''} onClick={() => onOpen(f.id)}>
                      <td onClick={e => e.stopPropagation()}><input type="checkbox" /></td>
                      <td><span className="id">{f.id}</span></td>
